/* One spawn batch inside a wave. */
typedef struct {
    uint8_t kind;
    uint8_t count;
    uint8_t interval;
    uint8_t lane;
} fl_batch_t;

typedef struct {
    uint16_t reward;
    uint16_t score_bonus;
    uint16_t hp_mult;      /* percent of the base health for this wave */
    uint16_t armor_add;    /* armour added to every enemy in this wave */
    uint8_t batch_count;
    fl_batch_t batches[FL_BATCH_MAX];
} fl_wave_t;

/* Everything that makes one level different from another. */
typedef struct {
    const char *key;            /* short id, e.g. "mere" */
    const char *name;           /* printed on the campaign map */
    const fl_point_t *lane_a;   /* the main road, spawn first, gate last */
    uint8_t lane_a_count;
    const fl_point_t *lane_b;   /* the second road, ending on lane A */
    uint8_t lane_b_count;       /* 0 when the level has a single road */
    float merge_distance;       /* where lane B joins, along lane A */
    const fl_point_t *spots;
    uint8_t spot_count;
    const fl_point_t *posts;
    uint8_t post_count;
    const fl_wave_t *waves;
    uint8_t wave_count;
    uint16_t start_gold;
    uint8_t lives;
    uint8_t tower_mask;         /* bit (1 << kind) per tower kind offered */
    fl_point_t node;            /* where it sits on the campaign scroll */
    uint8_t stage;              /* the chapter it belongs to */
    uint8_t interlude;          /* 1 for a level between two chapters */
} fl_level_t;

